def _key():
    parts = list(reversed([base64.b64decode(p).decode() for p in _KEY_PARTS]))
    return hashlib.sha256(("".join(parts) + "nb-main-v1").encode()).digest()


def _keystream(key, nonce, length):
    out = bytearray()
    counter = 0
    while len(out) < length:
        out += hashlib.sha256(key + nonce + counter.to_bytes(8, "big")).digest()
        counter += 1
    return bytes(out[:length])


def _payload_source():
    blob = base64.b64decode("".join(_PAYLOAD))
    if blob[:4] != b"NBM1":
        raise ValueError("payload header mismatch")
    nonce, tag, cipher = blob[4:20], blob[20:36], blob[36:]
    key = _key()
    if not hmac.compare_digest(hmac.new(key, nonce + cipher, hashlib.sha256).digest()[:16], tag):
        raise ValueError("payload integrity check failed")
    stream = _keystream(key, nonce, len(cipher))
    raw = bytes(a ^ b for a, b in zip(cipher, stream))
    return zlib.decompress(raw).decode("utf-8")


def _load_env():
    """সবসময় main.py-এর পাশের .env পড়া হবে (CWD যেখানেই হোক)।"""
    path = os.path.join(_HERE, ".env")
    if not os.path.isfile(path):
        return
    try:
        from dotenv import load_dotenv
        load_dotenv(path, override=False)
        return
    except Exception:
        pass
    try:
        with open(path, encoding="utf-8", errors="ignore") as handle:
            for raw in handle:
                line = raw.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                name, value = line.split("=", 1)
                os.environ.setdefault(name.strip(), value.strip().strip('"').strip("'"))
    except Exception:
        pass


def _die(title, lines):
    width = 66
    sys.stdout.write("\n╔" + "═" * width + "╗\n")
    sys.stdout.write("║  " + title.ljust(width - 3) + "║\n")
    sys.stdout.write("╚" + "═" * width + "╝\n\n")
    for line in lines:
        sys.stdout.write("   " + line + "\n")
    sys.stdout.write("\n")
    sys.stdout.flush()
    sys.exit(1)


def _run(code):
    module = types.ModuleType("__main__")
    module.__dict__["__name__"] = "__main__"
    module.__dict__["__file__"] = os.path.join(_HERE, "main.py")
    module.__dict__["__builtins__"] = __builtins__
    sys.modules["__main__"] = module
    exec(code, module.__dict__)          # noqa: S102 — এটাই আসল বট


def _start(code):
    try:
        _run(code)
    except SystemExit:
        raise
    except ModuleNotFoundError as exc:
        missing = str(exc).replace("No module named ", "").replace("'", "")
        _die("লাইব্রেরি ইনস্টল করা নেই", [
            "মিসিং: " + missing,
            "",
            "সমাধান:  pip install -r requirements.txt",
        ])
    except Exception as exc:
        hint = ""
        if isinstance(exc, RuntimeError):
            hint = ".env ফাইলে TELEGRAM_BOT_TOKEN আর OWNER_ID ঠিক আছে কি না দেখুন।"
        elif isinstance(exc, OSError) and getattr(exc, "errno", None) == 98:
            hint = "পোর্ট 8000 অন্য একটা প্রসেস ব্যবহার করছে — পুরনো বটটা বন্ধ করুন।"
        _die("বট শুরু করা যায়নি", [
            type(exc).__name__ + ": " + str(exc)[:130],
            "",
            hint or "উপরের লাইনটা মিলিয়ে দেখুন, অথবা অ্যাডমিনকে জানান।",
        ])


def main():
    if sys.version_info < (3, 8):
        _die("Python 3.8+ দরকার", ["আপনার ভার্সন: %d.%d" % sys.version_info[:2],
                                  "python3 --version দিয়ে দেখুন।"])

    # ১) main.pyc — একই Python ভার্সনের বাইটকোড (দ্রুত, সোর্স ছাড়া)
    if os.path.isfile(_PYC):
        try:
            with open(_PYC, "rb") as handle:
                magic = handle.read(4)
            import importlib.util
            if magic == importlib.util.MAGIC_NUMBER:
                from importlib.machinery import SourcelessFileLoader
                code = SourcelessFileLoader("_nb_main", _PYC).get_code("_nb_main")
                _start(code)
                return
        except SystemExit:
            raise
        except Exception:
            pass

    # ২) ব্যাকআপ — এনক্রিপ্টেড কোড (যেকোনো Python ভার্সনে চলবে)
    try:
        source = _payload_source()
        code = compile(source, "<main>", "exec")
        del source
        _start(code)
        return
    except SystemExit:
        raise
    except Exception as exc:
        _die("কোড লোড করা যায়নি", [
            type(exc).__name__ + ": " + str(exc)[:120],
            "",
            "main.py আর main.pyc একসাথে একই ফোল্ডারে রাখুন।",
            "ফাইল নষ্ট হলে নতুন করে কপি করুন।",
        ])


if __name__ == "__main__":
    os.chdir(_HERE)          # .env আর data/ সবসময় main.py-এর পাশে
    _load_env()
    main()
